import { Schema, model, type HydratedDocument, type InferSchemaType } from 'mongoose';
import { toClothingItemResponse, type ClothingItemDocument, type ClothingItemResponse } from './clothingItem.js';

// 'manual' outfits are built by the user; 'ai' outfits are generated by the app.
export const OUTFIT_SOURCES = ['manual', 'ai'] as const;

export const OUTFIT_LIMITS = {
  nameLength: 100,
  occasionLength: 100,
  maxItems: 20,
} as const;

const outfitSchema = new Schema(
  {
    owner: { type: Schema.Types.ObjectId, ref: 'User', required: true },
    name: { type: String, required: true, trim: true, maxlength: OUTFIT_LIMITS.nameLength },
    occasion: { type: String, trim: true, maxlength: OUTFIT_LIMITS.occasionLength, default: '' },
    items: [{ type: Schema.Types.ObjectId, ref: 'ClothingItem' }],
    source: { type: String, enum: OUTFIT_SOURCES, default: 'manual' },
  },
  { timestamps: true }
);

outfitSchema.index({ owner: 1, createdAt: -1 });
outfitSchema.index({ items: 1 });

export type OutfitDocument = HydratedDocument<InferSchemaType<typeof outfitSchema>>;

export const Outfit = model('Outfit', outfitSchema);

export interface OutfitResponse {
  id: string;
  name: string;
  occasion: string;
  source: string;
  items: ClothingItemResponse[];
  createdAt: Date;
  updatedAt: Date;
}

// Expects `items` to be populated; items that no longer exist are left out.
export function toOutfitResponse(outfit: OutfitDocument, items: ClothingItemDocument[]): OutfitResponse {
  return {
    id: outfit._id.toString(),
    name: outfit.name,
    occasion: outfit.occasion,
    source: outfit.source,
    items: items.map(toClothingItemResponse),
    createdAt: outfit.createdAt,
    updatedAt: outfit.updatedAt,
  };
}
